-- AI-JOB P0 business schema for MySQL 8.0.16+ / InnoDB.
-- Flyway executes this against the configured career_business database.
-- Agent-owned tables belong to a separate Python-managed database and are intentionally excluded.
-- UUIDs are generated by the application; updated_at is explicitly maintained by the application.
-- Logical polymorphic references, ownership checks and cross-row business rules are enforced by the application.

CREATE TABLE `app_user` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `email` VARCHAR(254) NOT NULL,
  `password_hash` VARCHAR(255) NOT NULL,
  `nickname` VARCHAR(30) NOT NULL,
  `role` VARCHAR(16) NOT NULL DEFAULT 'USER',
  `status` VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
  `token_version` INT UNSIGNED NOT NULL DEFAULT 0,
  `deleted_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_email` (`email`),
  KEY `idx_status_created_at_id` (`status`, `created_at`, `id`),
  CONSTRAINT `ck_app_user_1` CHECK (role IN ('USER','ADMIN')),
  CONSTRAINT `ck_app_user_2` CHECK (status IN ('ACTIVE','DISABLED','DELETED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `auth_session` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `family_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `token_hash` BINARY(32) NOT NULL,
  `csrf_hash` BINARY(32) NOT NULL,
  `parent_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
  `expires_at` DATETIME(3) NOT NULL,
  `rotated_at` DATETIME(3) NULL DEFAULT NULL,
  `revoked_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_token_hash` (`token_hash`),
  KEY `idx_user_id_status_expires_at` (`user_id`, `status`, `expires_at`),
  KEY `idx_family_id_status` (`family_id`, `status`),
  CONSTRAINT `ck_auth_session_1` CHECK (status IN ('ACTIVE','ROTATED','REVOKED','EXPIRED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_profile` (
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_version` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `target_role` VARCHAR(32) NULL DEFAULT NULL,
  `candidate_type` VARCHAR(16) NULL DEFAULT NULL,
  `cities_json` JSON NOT NULL,
  `min_monthly_salary_cents` INT UNSIGNED NULL DEFAULT NULL,
  `max_monthly_salary_cents` INT UNSIGNED NULL DEFAULT NULL,
  `confirmed_facts_json` JSON NOT NULL,
  `active_resume_version_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  PRIMARY KEY (`user_id`),
  CONSTRAINT `ck_user_profile_1` CHECK (candidate_type IS NULL OR candidate_type IN ('INTERNSHIP','CAMPUS','EXPERIENCED')),
  CONSTRAINT `ck_user_profile_2` CHECK (min_monthly_salary_cents IS NULL OR max_monthly_salary_cents IS NULL OR min_monthly_salary_cents <= max_monthly_salary_cents)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `skill_catalog` (
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `name` VARCHAR(100) NOT NULL,
  `parent_code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `enabled` TINYINT(1) NOT NULL DEFAULT 1,
  PRIMARY KEY (`code`),
  KEY `idx_parent_code_enabled` (`parent_code`, `enabled`),
  CONSTRAINT `ck_skill_catalog_1` CHECK (enabled IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `resume` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(100) NOT NULL,
  `latest_version_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `deleted_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_id_deleted_at_created_at_id` (`user_id`, `deleted_at`, `created_at`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `resume_version` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `resume_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version_no` INT UNSIGNED NOT NULL,
  `file_name` VARCHAR(255) NOT NULL,
  `storage_key` VARCHAR(512) NOT NULL,
  `mime_type` VARCHAR(100) NOT NULL,
  `size_bytes` BIGINT UNSIGNED NOT NULL,
  `sha256` BINARY(32) NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'UPLOADED',
  `parsed_facts_json` JSON NULL DEFAULT NULL,
  `confirmed_facts_json` JSON NULL DEFAULT NULL,
  `parse_meta_json` JSON NULL DEFAULT NULL,
  `confirmed_at` DATETIME(3) NULL DEFAULT NULL,
  `deleted_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_resume_id_version_no` (`resume_id`, `version_no`),
  KEY `idx_user_id_status_created_at` (`user_id`, `status`, `created_at`),
  KEY `idx_user_id_sha256` (`user_id`, `sha256`),
  CONSTRAINT `ck_resume_version_1` CHECK (size_bytes <= 10485760),
  CONSTRAINT `ck_resume_version_2` CHECK (status IN ('UPLOADED','PARSING','PARSED','CONFIRMED','FAILED','DELETED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `ability_evidence` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `skill_code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_type` VARCHAR(32) NOT NULL,
  `source_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `source_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `score` DECIMAL(5,1) NULL DEFAULT NULL,
  `confidence` DECIMAL(4,3) NOT NULL DEFAULT 0,
  `quote` TEXT NULL DEFAULT NULL,
  `rubric_version` VARCHAR(64) NOT NULL,
  `model_version` VARCHAR(100) NULL DEFAULT NULL,
  `prompt_version` VARCHAR(64) NULL DEFAULT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'VALID',
  `revoked_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id_skill_code_source_type_source_id_rubric_version` (`user_id`, `skill_code`, `source_type`, `source_id`, `rubric_version`),
  KEY `idx_user_id_skill_code_status_created_at_id` (`user_id`, `skill_code`, `status`, `created_at`, `id`),
  KEY `idx_task_id` (`task_id`),
  CONSTRAINT `ck_ability_evidence_1` CHECK (source_type IN ('RESUME_CLAIM','LEARNING_ANSWER','INTERVIEW_ANSWER')),
  CONSTRAINT `ck_ability_evidence_2` CHECK (status IN ('VALID','REVOKED')),
  CONSTRAINT `ck_ability_evidence_3` CHECK (score IS NULL OR score BETWEEN 0 AND 100),
  CONSTRAINT `ck_ability_evidence_4` CHECK (confidence BETWEEN 0 AND 1),
  CONSTRAINT `ck_ability_evidence_5` CHECK (source_type <> 'RESUME_CLAIM' OR score IS NULL)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_skill_snapshot` (
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `skill_code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `formula_version` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'ability-v1-trial',
  `score` DECIMAL(5,1) NULL DEFAULT NULL,
  `sample_count` INT UNSIGNED NOT NULL DEFAULT 0,
  `evidence_status` VARCHAR(16) NOT NULL DEFAULT 'MISSING',
  `last_evidence_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`user_id`, `skill_code`, `formula_version`),
  CONSTRAINT `ck_user_skill_snapshot_1` CHECK (evidence_status IN ('MISSING','LIMITED','SUFFICIENT')),
  CONSTRAINT `ck_user_skill_snapshot_2` CHECK (score IS NULL OR score BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `job_source` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `name` VARCHAR(100) NOT NULL,
  `type` VARCHAR(16) NOT NULL,
  `base_url` VARCHAR(1000) NULL DEFAULT NULL,
  `verification_status` VARCHAR(16) NOT NULL DEFAULT 'UNVERIFIED',
  `verification_note` TEXT NULL DEFAULT NULL,
  `verified_at` DATETIME(3) NULL DEFAULT NULL,
  `verified_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_verification_status_type` (`verification_status`, `type`),
  CONSTRAINT `ck_job_source_1` CHECK (type IN ('OFFICIAL','AUTHORIZED','USER_INPUT')),
  CONSTRAINT `ck_job_source_2` CHECK (verification_status IN ('VERIFIED','UNVERIFIED','DISABLED')),
  CONSTRAINT `ck_job_source_3` CHECK (type <> 'USER_INPUT' OR verification_status <> 'VERIFIED')
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `job` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `source_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `owner_user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `visibility` VARCHAR(16) NOT NULL DEFAULT 'PRIVATE',
  `current_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `status` VARCHAR(16) NOT NULL DEFAULT 'DRAFT',
  `source_url` VARCHAR(2000) NULL DEFAULT NULL,
  `verified_at` DATETIME(3) NULL DEFAULT NULL,
  `closed_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_visibility_status_verified_at_id` (`visibility`, `status`, `verified_at`, `id`),
  KEY `idx_owner_user_id_status_created_at_id` (`owner_user_id`, `status`, `created_at`, `id`),
  CONSTRAINT `ck_job_1` CHECK (visibility IN ('PUBLIC','PRIVATE')),
  CONSTRAINT `ck_job_2` CHECK (status IN ('DRAFT','ANALYZING','ACTIVE','CLOSED','FAILED')),
  CONSTRAINT `ck_job_3` CHECK ((visibility = 'PUBLIC' AND owner_user_id IS NULL) OR (visibility = 'PRIVATE' AND owner_user_id IS NOT NULL))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `job_version` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `version_no` INT UNSIGNED NOT NULL,
  `title` VARCHAR(100) NOT NULL,
  `company_name` VARCHAR(100) NOT NULL,
  `city_code` VARCHAR(12) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `role_code` VARCHAR(32) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `candidate_type` VARCHAR(16) NOT NULL,
  `min_monthly_salary_cents` INT UNSIGNED NULL DEFAULT NULL,
  `max_monthly_salary_cents` INT UNSIGNED NULL DEFAULT NULL,
  `currency` CHAR(3) CHARACTER SET ascii COLLATE ascii_bin NOT NULL DEFAULT 'CNY',
  `jd_text` MEDIUMTEXT NOT NULL,
  `content_hash` BINARY(32) NOT NULL,
  `requirements_json` JSON NULL DEFAULT NULL,
  `analysis_meta_json` JSON NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_job_id_version_no` (`job_id`, `version_no`),
  KEY `idx_city_code_candidate_type_role_code_created_at_id` (`city_code`, `candidate_type`, `role_code`, `created_at`, `id`),
  CONSTRAINT `ck_job_version_1` CHECK (candidate_type IN ('INTERNSHIP','CAMPUS','EXPERIENCED')),
  CONSTRAINT `ck_job_version_2` CHECK (min_monthly_salary_cents IS NULL OR max_monthly_salary_cents IS NULL OR min_monthly_salary_cents <= max_monthly_salary_cents)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `job_favorite` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id_job_id` (`user_id`, `job_id`),
  KEY `idx_user_id_created_at_id` (`user_id`, `created_at`, `id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `job_match_batch` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_version` BIGINT UNSIGNED NOT NULL,
  `resume_version_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'GENERATING',
  `input_snapshot_json` JSON NOT NULL,
  `score_version` VARCHAR(64) NOT NULL DEFAULT 'match-v1-trial',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_user_id_created_at_id` (`user_id`, `created_at`, `id`),
  CONSTRAINT `ck_job_match_batch_1` CHECK (status IN ('GENERATING','READY','FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `job_match_item` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `batch_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_version` INT UNSIGNED NOT NULL,
  `rank_no` INT UNSIGNED NOT NULL,
  `eligibility_status` VARCHAR(16) NOT NULL,
  `eligibility_json` JSON NOT NULL,
  `match_score` DECIMAL(5,1) NULL DEFAULT NULL,
  `components_json` JSON NOT NULL,
  `gaps_json` JSON NOT NULL,
  `reasons_json` JSON NOT NULL,
  `source_snapshot_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_batch_id_job_id` (`batch_id`, `job_id`),
  KEY `idx_batch_id_eligibility_status_rank_no` (`batch_id`, `eligibility_status`, `rank_no`),
  CONSTRAINT `ck_job_match_item_1` CHECK (eligibility_status IN ('PASS','FAIL','UNKNOWN')),
  CONSTRAINT `ck_job_match_item_2` CHECK (match_score IS NULL OR match_score BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `knowledge_document` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `title` VARCHAR(200) NOT NULL,
  `content` MEDIUMTEXT NOT NULL,
  `document_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `skill_codes_json` JSON NOT NULL,
  `source_url` VARCHAR(2000) NULL DEFAULT NULL,
  `license_note` VARCHAR(1000) NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
  `index_status` VARCHAR(16) NOT NULL DEFAULT 'PENDING',
  `created_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_status_index_status_updated_at_id` (`status`, `index_status`, `updated_at`, `id`),
  CONSTRAINT `ck_knowledge_document_1` CHECK (status IN ('ACTIVE','ARCHIVED')),
  CONSTRAINT `ck_knowledge_document_2` CHECK (index_status IN ('PENDING','READY','FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `question` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `root_question_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `question_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `stem` TEXT NOT NULL,
  `type` VARCHAR(32) NOT NULL DEFAULT 'TEXT_SCENARIO',
  `skill_codes_json` JSON NOT NULL,
  `difficulty` VARCHAR(16) NOT NULL DEFAULT 'MEDIUM',
  `source_type` VARCHAR(16) NOT NULL DEFAULT 'CURATED',
  `reference_answer` TEXT NOT NULL,
  `rubric_json` JSON NOT NULL,
  `citations_json` JSON NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'ACTIVE',
  `generated_task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `created_by` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_root_question_id_question_version` (`root_question_id`, `question_version`),
  KEY `idx_status_difficulty_source_type_created_at_id` (`status`, `difficulty`, `source_type`, `created_at`, `id`),
  UNIQUE KEY `uk_generated_task_id` (`generated_task_id`),
  CONSTRAINT `ck_question_1` CHECK (type IN ('TEXT_SCENARIO','TEXT_KNOWLEDGE')),
  CONSTRAINT `ck_question_2` CHECK (difficulty IN ('EASY','MEDIUM','HARD')),
  CONSTRAINT `ck_question_3` CHECK (source_type IN ('CURATED','GENERATED')),
  CONSTRAINT `ck_question_4` CHECK (status IN ('ACTIVE','ARCHIVED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `learning_plan` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `match_item_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_version` BIGINT UNSIGNED NOT NULL,
  `title` VARCHAR(200) NULL DEFAULT NULL,
  `daily_minutes` INT UNSIGNED NOT NULL,
  `days` INT UNSIGNED NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'GENERATING',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_user_id_status_created_at_id` (`user_id`, `status`, `created_at`, `id`),
  CONSTRAINT `ck_learning_plan_1` CHECK (status IN ('GENERATING','ACTIVE','COMPLETED','FAILED')),
  CONSTRAINT `ck_learning_plan_2` CHECK (daily_minutes BETWEEN 10 AND 120),
  CONSTRAINT `ck_learning_plan_3` CHECK (days BETWEEN 1 AND 14)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `learning_plan_item` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `plan_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `seq` INT UNSIGNED NOT NULL,
  `skill_code` VARCHAR(64) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `title` VARCHAR(200) NOT NULL,
  `kind` VARCHAR(16) NOT NULL,
  `estimated_minutes` INT UNSIGNED NOT NULL,
  `resource_refs_json` JSON NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'PENDING',
  `completed_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_plan_id_seq` (`plan_id`, `seq`),
  KEY `idx_plan_id_status_seq` (`plan_id`, `status`, `seq`),
  CONSTRAINT `ck_learning_plan_item_1` CHECK (kind IN ('READING','PRACTICE','INTERVIEW')),
  CONSTRAINT `ck_learning_plan_item_2` CHECK (status IN ('PENDING','IN_PROGRESS','COMPLETED')),
  CONSTRAINT `ck_learning_plan_item_3` CHECK (estimated_minutes BETWEEN 5 AND 120)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `learning_session` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `plan_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `plan_item_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `question_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `question_version` INT UNSIGNED NULL DEFAULT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'PREPARING',
  `version` INT UNSIGNED NOT NULL DEFAULT 1,
  `last_answer_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_id_status_created_at_id` (`user_id`, `status`, `created_at`, `id`),
  KEY `idx_plan_item_id_status` (`plan_item_id`, `status`),
  CONSTRAINT `ck_learning_session_1` CHECK (status IN ('PREPARING','ACTIVE','EVALUATING','COMPLETED','FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `learning_answer` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `session_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `content` TEXT NOT NULL,
  `content_hash` BINARY(32) NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'EVALUATING',
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `evaluation_json` JSON NULL DEFAULT NULL,
  `evaluated_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_session_id` (`session_id`),
  KEY `idx_task_id` (`task_id`),
  KEY `idx_user_id_created_at_id` (`user_id`, `created_at`, `id`),
  CONSTRAINT `ck_learning_answer_1` CHECK (status IN ('EVALUATING','EVALUATED','FAILED')),
  CONSTRAINT `ck_learning_answer_2` CHECK (CHAR_LENGTH(content) <= 10000)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `user_mistake` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `question_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `last_answer_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `wrong_count` INT UNSIGNED NOT NULL DEFAULT 1,
  `resolved` TINYINT(1) NOT NULL DEFAULT 0,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id_question_id` (`user_id`, `question_id`),
  KEY `idx_user_id_resolved_updated_at_id` (`user_id`, `resolved`, `updated_at`, `id`),
  CONSTRAINT `ck_user_mistake_1` CHECK (resolved IN (0,1))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `interview_session` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `job_version` INT UNSIGNED NOT NULL,
  `resume_version_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_version` BIGINT UNSIGNED NOT NULL,
  `input_snapshot_json` JSON NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'PREPARING',
  `question_limit` INT UNSIGNED NOT NULL DEFAULT 5,
  `current_question_no` INT UNSIGNED NOT NULL DEFAULT 0,
  `current_follow_up_no` INT UNSIGNED NOT NULL DEFAULT 0,
  `last_seq` INT UNSIGNED NOT NULL DEFAULT 0,
  `version` INT UNSIGNED NOT NULL DEFAULT 1,
  `pending_task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `plan_item_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `ended_at` DATETIME(3) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `idx_user_id_status_created_at_id` (`user_id`, `status`, `created_at`, `id`),
  KEY `idx_pending_task_id` (`pending_task_id`),
  CONSTRAINT `ck_interview_session_1` CHECK (question_limit BETWEEN 3 AND 10),
  CONSTRAINT `ck_interview_session_2` CHECK (current_follow_up_no <= 2),
  CONSTRAINT `ck_interview_session_3` CHECK (status IN ('PREPARING','WAITING_ANSWER','GENERATING','ENDING','COMPLETED','FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `interview_message` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `interview_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `seq` INT UNSIGNED NOT NULL,
  `role` VARCHAR(16) NOT NULL,
  `content` TEXT NOT NULL,
  `question_no` INT UNSIGNED NOT NULL,
  `follow_up_no` INT UNSIGNED NOT NULL DEFAULT 0,
  `question_message_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `skill_codes_json` JSON NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_interview_id_seq` (`interview_id`, `seq`),
  UNIQUE KEY `uk_question_message_id` (`question_message_id`),
  KEY `idx_interview_id_role_seq` (`interview_id`, `role`, `seq`),
  CONSTRAINT `ck_interview_message_1` CHECK (role IN ('ASSISTANT','USER')),
  CONSTRAINT `ck_interview_message_2` CHECK ((role = 'ASSISTANT' AND question_message_id IS NULL) OR (role = 'USER' AND question_message_id IS NOT NULL)),
  CONSTRAINT `ck_interview_message_3` CHECK (follow_up_no <= 2)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `interview_turn_evaluation` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `interview_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `answer_message_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `evaluation_json` JSON NOT NULL,
  `rubric_version` VARCHAR(64) NOT NULL,
  `overall_score` DECIMAL(5,1) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_answer_message_id` (`answer_message_id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_interview_id_created_at_id` (`interview_id`, `created_at`, `id`),
  CONSTRAINT `ck_interview_turn_evaluation_1` CHECK (overall_score IS NULL OR overall_score BETWEEN 0 AND 100)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `interview_report` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `interview_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `report_version` INT UNSIGNED NOT NULL DEFAULT 1,
  `report_json` JSON NOT NULL,
  `overall_score` DECIMAL(5,1) NULL DEFAULT NULL,
  `completion_type` VARCHAR(24) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_interview_id` (`interview_id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  CONSTRAINT `ck_interview_report_1` CHECK (overall_score IS NULL OR overall_score BETWEEN 0 AND 100),
  CONSTRAINT `ck_interview_report_2` CHECK (completion_type IN ('NORMAL','EARLY_END','NO_VALID_ANSWER'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `growth_advice` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `profile_version` BIGINT UNSIGNED NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'GENERATING',
  `suggestions_json` JSON NULL DEFAULT NULL,
  `cited_evidence_ids_json` JSON NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id` (`task_id`),
  KEY `idx_user_id_profile_version_created_at_id` (`user_id`, `profile_version`, `created_at`, `id`),
  CONSTRAINT `ck_growth_advice_1` CHECK (status IN ('GENERATING','READY','FAILED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `ai_task` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `operation` VARCHAR(32) NOT NULL,
  `resource_type` VARCHAR(32) NOT NULL,
  `resource_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `status` VARCHAR(24) NOT NULL DEFAULT 'QUEUED',
  `idempotency_key` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `input_versions_json` JSON NOT NULL,
  `input_snapshot_json` JSON NOT NULL,
  `agent_run_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `retry_of_task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `result_ref_json` JSON NULL DEFAULT NULL,
  `result_digest` BINARY(32) NULL DEFAULT NULL,
  `error_json` JSON NULL DEFAULT NULL,
  `stage` VARCHAR(100) NULL DEFAULT NULL,
  `progress` TINYINT UNSIGNED NULL DEFAULT NULL,
  `last_event_seq` BIGINT UNSIGNED NOT NULL DEFAULT 0,
  `deadline_at` DATETIME(3) NOT NULL,
  `finished_at` DATETIME(3) NULL DEFAULT NULL,
  `version` INT UNSIGNED NOT NULL DEFAULT 1,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_agent_run_id` (`agent_run_id`),
  UNIQUE KEY `uk_idempotency_key` (`idempotency_key`),
  KEY `idx_user_id_status_created_at_id` (`user_id`, `status`, `created_at`, `id`),
  KEY `idx_status_deadline_at_id` (`status`, `deadline_at`, `id`),
  KEY `idx_resource_type_resource_id_created_at` (`resource_type`, `resource_id`, `created_at`),
  CONSTRAINT `ck_ai_task_1` CHECK (progress IS NULL OR progress BETWEEN 0 AND 100),
  CONSTRAINT `ck_ai_task_2` CHECK (status IN ('QUEUED','RUNNING','SUCCEEDED','FAILED','CANCEL_REQUESTED','CANCELLED','EXPIRED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `ai_task_event` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `seq` BIGINT UNSIGNED NOT NULL,
  `event_type` VARCHAR(24) NOT NULL,
  `payload_json` JSON NOT NULL,
  `agent_run_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `agent_seq` BIGINT UNSIGNED NULL DEFAULT NULL,
  `expires_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_task_id_seq` (`task_id`, `seq`),
  UNIQUE KEY `uk_agent_run_id_agent_seq` (`agent_run_id`, `agent_seq`),
  KEY `idx_expires_at` (`expires_at`),
  CONSTRAINT `ck_ai_task_event_1` CHECK (event_type IN ('accepted','stage','delta','done','error','cancelled'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `outbox_event` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `topic` VARCHAR(32) NOT NULL,
  `aggregate_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `dedupe_key` VARCHAR(200) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `payload_json` JSON NOT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'PENDING',
  `attempts` INT UNSIGNED NOT NULL DEFAULT 0,
  `next_attempt_at` DATETIME(3) NOT NULL,
  `lease_owner` VARCHAR(100) NULL DEFAULT NULL,
  `lease_until` DATETIME(3) NULL DEFAULT NULL,
  `last_error` VARCHAR(1000) NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_dedupe_key` (`dedupe_key`),
  KEY `idx_status_next_attempt_at_id` (`status`, `next_attempt_at`, `id`),
  KEY `idx_status_lease_until` (`status`, `lease_until`),
  CONSTRAINT `ck_outbox_event_1` CHECK (topic IN ('AI_DISPATCH','AI_CANCEL','INDEX_SYNC','FILE_DELETE','AI_ERASE')),
  CONSTRAINT `ck_outbox_event_2` CHECK (status IN ('PENDING','PROCESSING','DONE','DEAD'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `api_idempotency` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `created_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `updated_at` DATETIME(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3),
  `user_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `http_method` VARCHAR(8) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `route_key` VARCHAR(255) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_key` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
  `request_digest` BINARY(32) NOT NULL,
  `task_id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NULL DEFAULT NULL,
  `http_status` SMALLINT UNSIGNED NULL DEFAULT NULL,
  `response_json` JSON NULL DEFAULT NULL,
  `status` VARCHAR(16) NOT NULL DEFAULT 'PROCESSING',
  `expires_at` DATETIME(3) NOT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_user_id_http_method_route_key_request_key` (`user_id`, `http_method`, `route_key`, `request_key`),
  KEY `idx_expires_at_status` (`expires_at`, `status`),
  CONSTRAINT `ck_api_idempotency_1` CHECK (status IN ('PROCESSING','COMPLETED'))
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;

CREATE TABLE `audit_log` (
  `id` CHAR(36) CHARACTER SET ascii COLLATE ascii_bin NOT NULL,
